// Corre una sola vez, al terminar el loop.
const s = $getWorkflowStaticData('global');
const r = s.resumen || { enviados: 0, saltados: 0, errores: 0, detalle: [] };
s.resumen = null;
return [{ json: {
  enviados: r.enviados, saltados: r.saltados, errores: r.errores,
  detalle: (r.detalle || []).slice(0, 100),
}}];

// Despachador proactivo — decide UN mensaje por lead, con tope global.
// Prioridad: recordatorio de link pendiente > nurturing por programa.
const lead = $('Split In Batches').item.json;
const cfg  = $('Config').first().json;

const idmc   = String(lead['ID Manychat'] || '').trim();
const toques = Number(lead['Toques enviados'] || 0);
const nombre = String(lead['Nombre'] || '').trim().split(' ')[0] || '';
const prog   = String(lead['Programa interés'] || 'No definido').trim();
const linkEnviado = lead['Link asesoría enviado'] === true;

// Guarda dura: el tope global se re-verifica acá, no sólo en la fórmula de Airtable.
if (!idmc)        return [{ json: { skip: true, motivo: 'sin ID Manychat', record_id: lead.id } }];
if (toques >= 2)  return [{ json: { skip: true, motivo: 'tope global alcanzado', record_id: lead.id } }];
if (lead['Agendan cita'] === true) return [{ json: { skip: true, motivo: 'ya agendó', record_id: lead.id } }];

// Normalización de programa: colapsa la doble grafía "Boarding School" / "Boarding IA"
// y todo lo que no mapea cae en 'general' (hoy 1.315 leads con "No definido" reciben silencio).
const P = prog.toLowerCase();
let key = 'general';
if (P.includes('boarding')) key = 'boarding';
else if (P.includes('aa familiar') || P.includes('académico') || P.includes('academico')) key = 'aa_familia';
else if (P.includes('summer') || P.includes('campamento')) key = 'summer';
else if (P.includes('pathway')) key = 'pathway';
else if (P.includes('gap') || P.includes('trabaj')) key = 'gap';

const LINKS = {
  boarding:   'promo.venttur.com/agendar-ema',
  aa_familia: 'promo.venttur.com/AAFamilia-Agendar',
  summer:     'promo.venttur.com/SummerCamp-Agendar',
  pathway:    'promo.venttur.com/PW_Alemania_Agendar',
  gap:        'promo.venttur.com/Estudiar-y-Trabajar-en-Australia',
  general:    'promo.venttur.com/agendar-ema',
};
const TXT = {
  boarding:'Boarding School', aa_familia:'Año Académico', summer:'Summer Camp',
  pathway:'Pathway en Alemania', gap:'Gap Year', general:'los programas',
};
const saludo = nombre ? `Hola ${nombre}` : 'Hola';
let motivo, p1, p2, p3;

if (linkEnviado) {
  // PRIORIDAD 1 — el reporte pide que esto sea la respuesta ESTÁNDAR para todo link pendiente.
  motivo = 'link_pendiente';
  p1 = `${saludo}, hace unos días te compartí el enlace para agendar tu asesoría y vi que aún no elegiste horario`;
  p2 = `Si no encontraste un horario que se ajuste a tu agenda, avísame y reviso disponibilidad manual`;
  p3 = `Cuando gustes, aquí lo tienes: ${LINKS[key]}`;
} else {
  motivo = 'nurturing';
  p1 = `${saludo}, me quedé con ganas de ayudarte a aterrizar lo de ${TXT[key]}`;
  p2 = `La duda más común de las familias es por dónde empezar y cuánto tiempo lleva el proceso`;
  p3 = `Si gustas lo revisamos juntos en una videollamada, sin compromiso: ${LINKS[key]}`;
}

// Una sola pregunta por mensaje (H6): estos textos no llevan ninguna.
const partes = [p1, p2, p3];
const preguntas = partes.join(' ').split('?').length - 1;
if (preguntas > 1) throw new Error(`Mensaje con ${preguntas} preguntas — viola la regla de una sola pregunta`);

return [{ json: {
  skip: false,
  motivo,
  key,
  record_id: lead.id,
  id_manychat: idmc,
  session_key: String(lead['Telefono'] || '').replace(/\D/g, ''),
  nombre,
  toques_nuevos: toques + 1,
  // Regla de Max (2026-08-18): al agotar el tope de 2 toques sin respuesta, el lead se cierra
  // como 'Perdida'. Si no llego al tope, se reescribe el estado que ya tenia (nunca se borra).
  estado_final: (toques + 1 >= 2)
    ? 'Perdida'
    : (String(lead['Estado conversación'] || '').trim() || 'Activa'),
  dry_run: cfg.dry_run === true || cfg.dry_run === 'true',
  texto: partes.filter(Boolean).join('\n\n'),
  mcBody: { subscriber_id: idmc, fields: [
    { field_name: 'parte1', field_value: p1 },
    { field_name: 'parte2', field_value: p2 },
    { field_name: 'parte3', field_value: p3 },
  ]},
}}];

// Memoria sintética: el agente tiene que saber qué le mandamos proactivamente,
// o cuando el lead responda va a contestar a ciegas (H4).
const d = $('Decidir mensaje').item.json;
return [{ json: {
  session_key: d.session_key,
  ai_message: { type: 'ai', content: d.texto },
}}];

