// Contador para el resumen final.
const s = $getWorkflowStaticData('global');
s.resumen = s.resumen || { enviados: 0, saltados: 0, errores: 0, detalle: [] };
const d = $('Decidir mensaje').item.json;
if (d.skip) { s.resumen.saltados++; }
else if (d.dry_run) { s.resumen.saltados++; s.resumen.detalle.push(`DRY-RUN ${d.record_id} ${d.motivo}`); }
else { s.resumen.enviados++; s.resumen.detalle.push(`${d.record_id} ${d.motivo}`); }
return $input.all();
